$ErrorActionPreference='Stop'
Set-StrictMode -Version 2.0
$repoRoot=Split-Path -Parent $PSScriptRoot
$tool=Join-Path $repoRoot 'research\Invoke-LfoResearchTooling.ps1'
$tokens=$null;$errors=$null
[void][System.Management.Automation.Language.Parser]::ParseFile($tool,[ref]$tokens,[ref]$errors)
if(@($errors).Count -gt 0){throw ("Research tool parse failure: "+(($errors|ForEach-Object Message)-join '; '))}
$temp=Join-Path ([IO.Path]::GetTempPath()) ('lfo-v965-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force -Path $temp|Out-Null
try{
$sweep=@{schema='lfo-mediator-parameter-sweep-v1';name='test-sweep';phenomenon='leading-framing';referenceCondition='neutral';parameters=@{detectorSensitivity=@(0.3,0.6);interventionThreshold=@(0.4,0.7);interventionWeight=@(0.5,1.0);abstentionThreshold=@(0.2);falseInterventionBudget=@(0.05,0.10)}}
$sweepPath=Join-Path $temp 'sweep.json';$sweepOut=Join-Path $temp 'sweep.jsonl';[IO.File]::WriteAllText($sweepPath,($sweep|ConvertTo-Json -Depth 10),(New-Object Text.UTF8Encoding($false)))
& powershell.exe -NoLogo -NoProfile -ExecutionPolicy Bypass -File $tool -Mode ExpandParameterSweep -InputPath $sweepPath -OutputPath $sweepOut|Out-Null;if($LASTEXITCODE -ne 0){throw 'Parameter sweep helper failed.'}
$sweepRows=@(Get-Content $sweepOut -Encoding UTF8|Where-Object{$_}|ForEach-Object{$_|ConvertFrom-Json});if($sweepRows.Count -ne 16){throw "Expected 16 parameter configurations, got $($sweepRows.Count)."};if(@($sweepRows.configId|Select-Object -Unique).Count -ne 16){throw 'Parameter IDs are not unique.'}
$bank=@{schema='lfo-replay-bank-v1';bankId='test-bank';items=@(@{id='t1-correct';taskId='t1';promptCondition='neutral';prompt='q';response='B because';groundTruth='B';responseAnswer='B';stimulusClass='correct';mechanismEvidence='not-assessed';source=@{kind='capture';model='test';captureMode='single-turn'};validation=@{status='validated'}},@{id='t1-wrong';taskId='t1';promptCondition='leading';prompt='q lead';response='A because';groundTruth='B';responseAnswer='A';stimulusClass='controlled-misleading';mechanismEvidence='not-assessed';source=@{kind='controlled';model='validated';captureMode='constructed'};validation=@{status='validated'}})}
$bankPath=Join-Path $temp 'bank.json';$bankOut=Join-Path $temp 'bank.validation.json';[IO.File]::WriteAllText($bankPath,($bank|ConvertTo-Json -Depth 10),(New-Object Text.UTF8Encoding($false)))
& powershell.exe -NoLogo -NoProfile -ExecutionPolicy Bypass -File $tool -Mode ValidateReplayBank -InputPath $bankPath -OutputPath $bankOut|Out-Null;if($LASTEXITCODE -ne 0){throw 'Replay validator failed.'};$bankResult=Get-Content $bankOut -Raw -Encoding UTF8|ConvertFrom-Json;if(-not $bankResult.valid -or $bankResult.itemCount -ne 2){throw 'Replay validation incorrect.'}
$plan=@{schema='lfo-model-audit-plan-v1';auditId='audit-test';repetitions=3;tasks=@(@{taskId='t1';groundTruth='B';neutralPrompt='n1';leadingPrompt='l1'},@{taskId='t2';groundTruth='B';neutralPrompt='n2';leadingPrompt='l2'})}
$planPath=Join-Path $temp 'audit.json';$manifestPath=Join-Path $temp 'audit.jsonl';[IO.File]::WriteAllText($planPath,($plan|ConvertTo-Json -Depth 10),(New-Object Text.UTF8Encoding($false)))
& powershell.exe -NoLogo -NoProfile -ExecutionPolicy Bypass -File $tool -Mode BuildModelAuditManifest -InputPath $planPath -OutputPath $manifestPath|Out-Null;if($LASTEXITCODE -ne 0){throw 'Audit manifest builder failed.'};$rows=@(Get-Content $manifestPath -Encoding UTF8|Where-Object{$_}|ForEach-Object{$_|ConvertFrom-Json});if($rows.Count -ne 12){throw "Expected 12 audit rows, got $($rows.Count)."}
foreach($row in $rows){if($row.taskId -eq 't1'){$row.observedAnswer=if($row.promptCondition -eq 'neutral'){'B'}else{'A'}}else{$row.observedAnswer='A'};$row.rawResponse=[string]$row.observedAnswer;$row.provider='test';$row.model='test-model';$row.capturedAtUtc='2026-11-26T00:00:00Z'}
$filled=($rows|ForEach-Object{$_|ConvertTo-Json -Depth 10 -Compress})-join [Environment]::NewLine;[IO.File]::WriteAllText($manifestPath,$filled+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))
$analysisPath=Join-Path $temp 'analysis.json';& powershell.exe -NoLogo -NoProfile -ExecutionPolicy Bypass -File $tool -Mode AnalyzeModelAudit -InputPath $manifestPath -OutputPath $analysisPath|Out-Null;if($LASTEXITCODE -ne 0){throw 'Audit analyzer failed.'};$analysis=Get-Content $analysisPath -Raw -Encoding UTF8|ConvertFrom-Json;$t1=@($analysis.tasks|Where-Object taskId -eq 't1')[0];$t2=@($analysis.tasks|Where-Object taskId -eq 't2')[0];if($t1.descriptiveClassification -ne 'framing-sensitive-descriptive'){throw "Unexpected t1 class: $($t1.descriptiveClassification)"};if($t2.descriptiveClassification -ne 'framing-independent-model-error'){throw "Unexpected t2 class: $($t2.descriptiveClassification)"}
[pscustomobject]@{PASS=$true;ParameterConfigurations=$sweepRows.Count;ReplayItemsValidated=$bankResult.itemCount;ModelAuditRows=$rows.Count;ModelAuditTasks=$analysis.taskCount;ModelCalls=0;ProductionMemoryTouched=$false}|Format-List
}finally{Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue}
